INSERT INTO "gaps" ("gap_id", "category", "priority", "status", "skill", "section", "description", "created_at", "created_by_session", "updated_at", "updated_by_session", "falsification_condition", "confidence_interval", "shift_conditions", "named_dissenter", "mining_addressability") VALUES ('GAP-041', 'RP', 'P2', 'OPEN', 'multilingual-research', 'accessible-circulation-geometry', 'THE DISCOVERY-CATALOGUE STRATUM IS CLOSED IN THIS ENVIRONMENT, AND THREE BATCHES HAVE NOW EACH DISCOVERED IT SEPARATELY. Measured, all persisted as artefacts: catalog.hathitrust.org 403 + Cloudflare interstitial (batch 18); discover.libraryhub.jisc.ac.uk 403 + Cloudflare interstitial, twice (batch 19); trid.trb.org HTTP 200 serving a JS shell with no extractable record, although the page reports 20 results and the string Templer occurs in it five times (batch 19). NONE OF THESE IS A NULL RESULT. Nothing whatever is established about what HathiTrust, Jisc or TRID hold, and a later batch must not cite these as evidence of absence. WHAT THE PATTERN MEANS FOR PLANNING, WHICH IS THE POINT OF FILING IT: the pre-1990 layer this project keeps reaching for lives in library catalogues and technical-report indexes, and that is precisely the stratum this environment cannot see. Batches 17, 18 and 19 each independently built a retrieval ladder, each hit the same wall in a different place, and each recorded it locally. THE ROUTES THAT DO WORK, derived from the same three batches, are DEPOSIT-BASED rather than catalogue-based: ERIC (holds what was deposited in it -- it served ED184280 in full), Crossref (holds what publishers deposited), Open Library and Internet Archive (hold what was digitised), OpenAlex and CORE intermittently on a shared-IP daily budget. GOOGLE BOOKS IS NOT MERELY EXHAUSTED AND THE DISTINCTION MATTERS: batch 18 read its 429 as a daily quota and GAP-040 records it that way; queried again two days later the body reads quota_limit_value ''0'', a ZERO allocation for this project. It will not reset and no batch should spend a query discovering that again. ONE QUERY-SHAPE LESSON WORTH MORE THAN THE WHOLE LADDER: batch 18 searched Open Library for Walter 1971 BY TITLE and got 0; batch 19 searched the same index BY PUBLISHER, publisher:''Disabled Living Foundation'', and got 99 records with the target among them. Same index, same day''s coverage, opposite result. R14 says a zero-yield search is evidence of absence only if the query was well-formed, and for an institutional report the well-formed query is often the PUBLISHER, not the title -- an institutional report''s title is unstable across catalogues while its issuing body is not. WHAT IS OWED: this is a planning fact, not a defect to fix. The action it implies is that Walter 1971 and Elmer 1957 should be handed to document delivery -- OCLC 222208 and LCCN 77502052 for Walter; ProQuest Dissertations or the University of Illinois repository for Elmer -- rather than to a fourth retrieval ladder. GAP-026 already said this in general terms one batch ago; this gap gives it the identifiers and the negative evidence that make it actionable.', '2026-09-20 03:14', 'session_2026-09-20-research-batch-19-pre1990-chain-steinfeld-walter-templer', '2026-09-20 03:14', 'session_2026-09-20-research-batch-19-pre1990-chain-steinfeld-walter-templer', NULL, NULL, NULL, NULL, NULL);
UPDATE "gaps" SET "description" = 'GAP-028 IS ANSWERED, AND THE ANSWER IS THAT 1:12 WAS MEASURED AND FOUND WANTING BEFORE IT WAS ADOPTED. GAP-028 asked whether the 1:12 threshold is anchored in measurement. REF-01005 (Steinfeld, Schroeder and Bishop 1979, HUD-PDR 397, ERIC ED184280, full text retrieved and persisted this batch) settles it. (1) THE MEASUREMENT EXISTS. A purpose-built adjustable 40-foot ramp, 124 disabled participants, slope stepped 1:12 then 1:16 then 1:20, success judged on distance, time and pulse recovery to within ten beats of resting. (2) IT FOUND 1:12 INADEQUATE: almost half the wheelchair users could not negotiate the full length at 1:12 and about a third could not travel even 5 feet; every wheelchair user completed 40 feet at 1:20, though only three reached that trial. (3) THE STUDY WAS COMMISSIONED TO IMPROVE THE VERY STANDARD THAT CARRIES 1:12 — its Foreword says the six-report series was sponsored to make buildings accessible "through improving the American National Standards Institute A117 standard". (4) ITS OWN RECOMMENDATION TABLE RESTS PARTLY ON OTHERS: Table 13 footnote c reads "Based on research of others (Templer, 1977 and Walter, 1971)", so the chain has three nodes and this project holds one. (5) WALTER 1971 AND STEINFELD 1979 CONVERGE at 1:16 over 20 feet for at least 95 percent of wheelchair users, per page 163 — held on Steinfeld testimony alone, so it is ONE document counted once until Walter is retrieved. WHAT THIS DOES NOT DO: it does not supply a current anchor. Owner ruling 2026-09-18 places 1979 work as historical grounding rather than a present standard, so REF-01005 is admitted T3 grey and parameter 3 x MOB stays undetermined. WHAT IS NOW OWED: retrieve Walter 1971 (candidate 109, record verified) and Templer 1977 (candidate 115) — the two remaining nodes of the chain. Derive the state rather than quoting this: select disposition, title from search_candidates where candidate_id in (109,110,111,115). || CORRECTED 2026-09-20: BATCH 19 WORKED BOTH OWED NODES. NEITHER IS RETRIEVED; BOTH ARE MATERIALLY NARROWED, AND ONE CLAUSE OF THIS GAP NEEDS QUALIFYING. (1) THE QUALIFICATION, WHICH RUNS AGAINST THIS GAP''S OWN FRAMING: clause (4) says Table 13 ''rests partly on others'' and treats Templer and Walter as the two remaining nodes of THE 1:12 CHAIN. The footnote marker c appears on the 1:8 and 1:10 rows ONLY, not on 1:12 or 1:16 -- derive it at pypdf page index 56, and note it is coherent rather than noise because Table 12 shows the study tested exactly 1:12, 1:16 and 1:20, so the warranted bands are precisely the two OUTSIDE its tested range. On that reading the named warrant covers the permissive end of the table and the 1:12 and 1:16 rows rest on Steinfeld''s own data, which means Templer and Walter are not nodes of the 1:12 chain at all. Recorded as extraction 56 and held as A READING, NOT AS SETTLED: these are single characters on a damaged scan and a cleaner copy of page 57 decides it. (2) TEMPLER: ''Templer, 1977'' does not resolve to any indexed item, and John A. Templer''s corpus is stairs end to end -- 1974 dissertation (the one this bibliography actually lists), 1978 NBS IR 78-1554 ''An analysis of the behavior of stair users'', 1984 ''The Forgiving Stair'', 1989 ''The Soft Stair''. Four items, fifteen years, no ramp study, nothing dated 1977. ERIC author:Templer returns 33 records with none architectural and ERIC Templer+stairs returns 0, which is a well-formed negative rather than a query-shape failure. Candidate 115''s title over-claimed it as ''the ramp-slope research'' and is corrected. Candidate 117 stages the 1978 NBS report as the nearest RESOLVABLE neighbour, explicitly without claiming it is the referent. (3) WALTER: the year 1971 is now corroborated by a Library of Congress MARC record, which matters because this bibliography''s own year digits for Walter are OCR-damaged and unreadable. The route this gap and candidate 109 both named next -- Jisc Library Hub Discover -- IS CLOSED: HTTP 403 behind a Cloudflare interstitial, twice. What batch 19 adds instead is the holdings layer that makes document delivery actionable: OCLC 222208, LCCN 77502052, ISBN-10 0901908053, LC class NA2545.P5 D5. (4) CLAUSE (5) OF THIS GAP STANDS UNCHANGED and should not be read as weakened: the 1:16 convergence is still ONE document counted once, on Steinfeld''s testimony about Walter, until Walter itself is read.', "updated_at" = '2026-09-20 03:13', "updated_by_session" = 'session_2026-09-20-research-batch-19-pre1990-chain-steinfeld-walter-templer' WHERE "gap_id" = 'GAP-037';

-- search_executions: 3 insert(s), 0 update(s)
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation") VALUES (88, 'accessible-circulation-geometry', 'US', 'EN', 3, 'grey', 'intrinsic', 'BACKWARD MINING PASS over REF-01005 (Steinfeld, Schroeder and Bishop 1979, HUD-PDR 397, ERIC ED184280). Not an API query: no Crossref deposit exists for this report, so the reference list was transcribed from the persisted PDF at pypdf page indices 167-169 and scored with named screens. Derive the yield: python3 scripts/research/mining_screen.py --ref REF-01005 --compare', NULL, 'pdf-bibliography', 'systematic', 'backward', 38, 38, 0, 'saturated', NULL, NULL, 0, 'session_2026-09-20-research-batch-19-pre1990-chain-steinfeld-walter-templer', '2026-09-20 03:03', 'THREE OF FOUR PRE-REGISTERED PREDICTIONS FALSIFIED, AND THE REASONING BEHIND THE SURVIVING ONE WAS ALSO WRONG. Derive every figure here: python3 scripts/research/mining_screen.py --ref REF-01005 --compare. P1a FALSIFIED -- 38 references, not the 60-plus predicted. P1b FALSIFIED -- slope-strict scores 1-2, below the predicted 3-12 band. NOTE AGAINST MYSELF: my own pre-registered falsification condition said ''falsified if 0 or >=20'', which 1-2 does not trigger. The point prediction failed and the threshold I set to catch it was too lax to fire. Recording both rather than hiding behind the looser test. P1c FALSIFIED -- slope-loose scores 1-3 against slope-strict''s 1-2, nowhere near 3x. THE REASON I GAVE WAS WRONG IN A WAY WORTH KEEPING: I predicted the bare stem accessib would fire on everything because the report is an accessibility report. It fires on almost nothing, because the BIBLIOGRAPHY is not an accessibility bibliography -- it is a HUMAN FACTORS AND ERGONOMICS bibliography (Damon, Diffrient, Kroemer, McCormick, Murrell, Poulton, Human Factors and Applied Ergonomics as the recurring venues). A 1979 federal accessibility report drew its authority from ergonomics, not from a disability literature, and that is a finding about the period rather than about the screen. P1d CONFIRMED BUT WITH A DISCREPANCY THAT MATTERS MORE THAN THE PREDICTION: both appear, and the Templer entry is 1974 on STAIR SHAPE, while Table 13 footnote c cites ''Templer, 1977''. Templer 1977 IS NOT IN THIS BIBLIOGRAPHY. THE YIELD IS A FLOOR, NOT A COUNT: the OCR is damaged, so an entry whose title is mangled below the screen''s terms is a false negative, and the band''s ceiling says how much could be hidden. TWO SLOPE-TITLED ENTRIES: Elmer C.D. (candidate 110, scores in the conservative band -- ''ramp'' is legible) and Corlett et al. ''Ramps or stairs'' in Applied Ergonomics 3 (ceiling only -- ''stairs'' is legible, ''Ramps'' is not, newly staged this pass). WALTER DOES NOT SCORE AT ALL, and that is the most instructive result: it is the single most slope-relevant item in the list, and its title in this bibliography carries no slope term because ''Part 3: Ramp gradients'' is a part title. A title screen cannot see it. Recorded so no later reader reads a low yield as a thin literature.', 0, 'Pre-registered in scratchpad/<session>/priors.md and committed at 2026-09-20 02:46, BEFORE the bibliography was transcribed or any screen run. P1a: bibliography holds at least 60 references, confidence 0.75. P1b: slope-strict yield between 3 and 12, confidence 0.6. P1c: slope-loose yield at least 3x slope-strict, because REF-01005 is an ACCESSIBILITY report and slope-loose carries the bare stem accessib, confidence 0.7. P1d: both Templer and Walter appear as discrete entries, confidence 0.8. Instrument chosen in advance: slope-strict is PRIMARY; slope-loose is pre-emptively disqualified as a relevance measure on this anchor and reported only for comparability.');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation") VALUES (89, 'accessible-circulation-geometry', 'UK', 'EN', 3, 'grey', 'national', 'WALTER 1971 RETRIEVAL, six routes: (1) discover.libraryhub.jisc.ac.uk/search?keyword=four%20architectural%20movement%20studies&format=json (2) same host, keyword=architectural%20movement%20studies%20wheelchair (3) googleapis.com/books/v1/volumes?q=%22four+architectural+movement+studies%22 (4) api.openalex.org title.search (5) api.wellcomecollection.org catalogue query (6) api.core.ac.uk v3 search (7) archive.org advancedsearch by PUBLISHER ''Disabled Living Foundation'' (8) openlibrary.org search.json publisher:%22Disabled+Living+Foundation%22 limit=100', NULL, 'multi-catalogue', 'systematic', 'none', 99, 99, 0, 'partial', NULL, NULL, 0, 'session_2026-09-20-research-batch-19-pre1990-chain-steinfeld-walter-templer', '2026-09-20 03:10', 'THE ASSIGNED ROUTE IS CLOSED AND A DIFFERENT ONE ANSWERED. JISC IS UNREACHABLE FROM THIS ENVIRONMENT: both queries returned HTTP 403 carrying a Cloudflare ''Just a moment...'' interstitial. NOTHING IS ESTABLISHED ABOUT WHAT JISC HOLDS -- this is a BLOCKED ROUTE, not a null, and it is the second library discovery catalogue in two batches to fail this way (HathiTrust, batch 18). Candidate 109 named Jisc as its NEXT ROUTE, UNTRIED; that route is now closed and the candidate should stop pointing at it. P2a FALSIFIED AS WRITTEN, CONFIRMED IN SUBSTANCE: Jisc returned nothing, but the underlying expectation -- that an authoritative catalogue record exists and is reachable -- held, via Open Library searched BY PUBLISHER rather than by title. That is the query-shape lesson of R14 arriving as a positive: batch 18 searched Open Library for the TITLE and got 0; searching for the PUBLISHER returns 99 DLF records and the target sits among them. P2b CORRECT: no full text, and none of these routes could have supplied it. WHAT IS NEW, AND IT IS NOT THE RECORD: batch 18 ALREADY extracted Open Library OL4653562M in full -- Felix Walter, DLF, London, 1971, 60 pp -- and candidate 109 already carries it. I briefly believed batch 18 had missed it and checked before recording that; it had not. What this pass adds is the HOLDINGS LAYER the earlier note does not carry: ISBN-10 0901908053, LCCN 77502052, OCLC 222208, LC class NA2545.P5 D5, Dewey 729/.2, single edition, source record marc:marc_loc_2016 (a Library of Congress MARC record, which is why the 1971 date is authoritative rather than inferred). THOSE IDENTIFIERS ARE THE POINT: GAP-026 says what is needed is document delivery, not another search. An OCLC number and an LCCN convert ''find Walter 1971'' into ''request OCLC 222208'', which is an ILL action a human can take. GOOGLE BOOKS IS NOT MERELY EXHAUSTED: the 429 body reads quota_limit_value ''0'' -- a ZERO daily allocation, not a quota that resets. Batch 18 recorded it as a daily quota; two days later the limit is still 0, so it is structurally unavailable here and no future batch should spend a query testing for a reset. OPENALEX AND CORE both 429''d on a shared-IP daily budget (OpenAlex retryAfter ~75000s), though one later OpenAlex call in this same batch succeeded -- the budget is intermittent, not uniformly closed. WELLCOME: HTTP 200, 0 results, a genuine null from a reachable index, but Wellcome is a health-and-medicine library and an architectural report is out of its scope, so this is R14 ''wrong index'', not evidence of absence.', 0, 'Pre-registered in scratchpad/<session>/priors.md, committed 2026-09-20 02:46. P2a: Jisc returns a CATALOGUE RECORD, p=0.65, because it aggregates UK research-library catalogues and this is a UK institutional report. P2b: Jisc returns FULL TEXT, p=0.10 -- it is a discovery service over catalogues. I pre-committed to counting locator verification plus named holding libraries as a SUCCESS rather than moving the goalposts to full text afterwards. P2c: the author is not what batch 17 first staged, p=0.7.');
INSERT INTO "search_executions" ("exec_id", "slug", "jurisdiction", "language", "target_tier", "target_evidence_type", "target_scope", "query_text", "terms_used", "engine", "depth_method", "mining_direction", "results_found", "results_screened", "results_admitted", "saturation_signal", "admitted_ref_ids", "deferred_reason", "backfill", "created_by_session", "created_at", "findings_note", "harm_finding", "prior_expectation") VALUES (90, 'accessible-circulation-geometry', 'US', 'EN', 3, 'grey', 'intrinsic', 'TEMPLER 1977 IDENTIFICATION, seven routes: (1) api.ies.ed.gov/eric/?search=author%3A%22Templer%22&rows=25 (2) api.openalex.org/works?filter=title.search:stair%20shape%20human%20movement (3) api.crossref.org/works?query.author=Templer&query.bibliographic=ramp+slope (4) api.openalex.org/works?filter=raw_author_name.search:Templer,publication_year:1977 (5) trid.trb.org/Results?q=Templer%20stairs (6) api.crossref.org/works?query.bibliographic=Templer+stair+shape+human+movement (7) api.ies.ed.gov/eric/?search=%22Templer%22%20AND%20%22stairs%22', NULL, 'multi-index', 'systematic', 'none', 43, 43, 0, 'saturated', NULL, NULL, 0, 'session_2026-09-20-research-batch-19-pre1990-chain-steinfeld-walter-templer', '2026-09-20 03:10', 'TEMPLER 1977 DOES NOT RESOLVE TO ANY INDEXED ITEM, AND THE SURNAME IS NOW SETTLED AS John A. Templer, A STAIRS RESEARCHER. THE NEGATIVE IS WELL-FORMED, WHICH IS WHAT MAKES IT USABLE (R14). ERIC author:\"Templer\" returns 33 records -- a healthy result set, so the query shape is sound -- and NOT ONE is architectural: they are Bill Templer (education/politics), Lois Templer, Andrew J. Templer (management), Donald I. Templer (psychology, death-anxiety scales), Sally Templer. ERIC \"Templer\" AND \"stairs\" returns 0. A well-formed author query returning 33 and a topic conjunction returning 0 is GENUINE ABSENCE IN ERIC, not a query-shape failure -- and ERIC being an education index, absence there says nothing about the built-environment literature. P3b CORRECT AT 0.2. OpenAlex raw_author_name Templer + year 1977 returns 10, all of them Jerry W. Templer (ENT surgery), Donald I. Templer (psychology), Andrew J. Templer (management) or J.C. Templer. NO J.A. TEMPLER IN 1977 IN EITHER INDEX. P3a FALSIFIED: TRID served a 200 with a results page, and the page does not carry a single /View/ record id -- the markup is JS-rendered, so what came back is a shell. ''Templer'' appears 5 times in the body but no record is extractable. NOTHING IS ESTABLISHED ABOUT WHAT TRID HOLDS; treat this as a blocked route like Jisc, not as a null. WHAT DID RESOLVE, VIA CROSSREF ON THE DISSERTATION TITLE REF-01005''S OWN BIBLIOGRAPHY CARRIES: John A. Templer''s indexed corpus is stairs, end to end -- ''An analysis of the behavior of stair users'', John A Templer, Gary M Mullet, John Archea, Stephen T Margulis, 1978, NBS internal report, DOI 10.6028/nbs.ir.78-1554; ''The Forgiving Stair'', 1984, Human Factors Society; ''The Soft Stair: Falls Induced by a Laboratory Stair'', 1989. Together with the 1974 dissertation ''Stair shape and human movement'' that REF-01005''s bibliography actually lists, that is FOUR Templer items spanning fifteen years and NOT ONE OF THEM IS ABOUT RAMPS, and not one is dated 1977. P3e ANSWERED IN AN UNEXPECTED DIRECTION: the ambiguity is not between several 1977 Templers, it is that there is no 1977 Templer at all and the nearest neighbours are 1974 and 1978. STILL NOT GUESSED, PER THE ASSIGNMENT: the 1978 NBS report is one year off and would be a plausible preprint-dated citation, and the 1974 dissertation is the one the report itself lists. Either could be footnote c''s referent and this pass does not choose. THE STRUCTURAL FINDING IS INDEPENDENT OF WHICH ONE IT IS: Table 13''s footnote c warrants the 1:8 and 1:10 rampway bands on two named parties, and one of them has no ramp research to his name.', 0, 'Pre-registered in scratchpad/<session>/priors.md, committed 2026-09-20 02:46. P3a TRID holds a Templer 1977 record p=0.5. P3b ERIC holds it p=0.2 -- ERIC is an education index and held REF-01005 only because HUD deposited it there, a deposit fact rather than coverage. P3c NTIS p=0.3. P3d at least one of the three returns something p=0.7. P3e more than one distinct Templer 1977 item exists and disambiguation is required p=0.4; if so, record the ambiguity and do not resolve it by picking the likeliest. Batch 18 section 9 item 3, carried forward verbatim: WHICH TEMPLER IS LOAD-BEARING IS UNRESOLVED AND MUST NOT BE GUESSED.');

-- search_candidates: 2 insert(s), 3 update(s)
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at", "resolved_ref_id") VALUES (116, 88, 'accessible-circulation-geometry', NULL, 'PENDING-VERIFICATION', 'Corlett et al. — [Ramps] or stairs, in Applied Ergonomics 3 (reference-list entry in REF-01005, OCR-damaged)', 'no DOI; entry in REF-01005''s printed bibliography, pypdf page index 167. Journal and volume legible as ''APpi.ie.d ergbnilmrev,..3''', 'UNVERIFIED', 3, 0, 'HYPOTHESIS, AND THE TITLE IS PARTLY A GUESS -- flagged now so R15 catches it on resolution. The OCR reads "*.a.:''Rip''p'':-., ... iii...-stafrs, -11i'',APpi.ie.d ergbnilmrev,..3". ''stairs'' is legible; ''Ramps'' IS NOT -- only a capital R and a rough shape. THE TITLE MAY NOT CONTAIN ''Ramps'' AT ALL. It is staged because a paper comparing ramps to stairs in Applied Ergonomics, cited by the 1979 HUD report, would sit directly on parameter 3 and would be a pre-1990 node this project does not hold. It scores in the CEILING band only of every screen, never the floor, for exactly this reason.', 'Surfaced by the REF-01005 backward pass (exec 88). Authors as OCR''d: "Corle.-tt;t:N:'',-Huichesy :,e.;,-:Det.,Utill,,,L,M..and 6goiens4k.1" -- read as Corlett, [E].N., Hu[t]ches[on], [C]., De[L]u[gan], L.M. and [Ro]go[z]ens[ki], [J]. EVERY ONE OF THOSE SURNAMES AFTER THE FIRST IS RECONSTRUCTED FROM DAMAGED CHARACTERS AND NONE IS CONFIRMED. CLAUDE.md 5(c) forbids supplying a bibliographic field from memory when a payload is in hand, so they are recorded as read, with the damage visible, and not repaired. RESOLUTION ROUTE: Applied Ergonomics volume 3 is 1972 and IS indexed -- Crossref or ScienceDirect by journal plus volume plus title fragment should settle author list, exact title and pages in one retrieval. That is a cheap, well-formed query and it is owed. VERBATIM OCR PRESERVED in the derived artefact for this pass (retrieval-log/<session>/08263082ebdda8eb.json, entry with alpha_position C).', 'session_2026-09-20-research-batch-19-pre1990-chain-steinfeld-walter-templer', '2026-09-20 03:03', NULL);
INSERT INTO "search_candidates" ("candidate_id", "exec_id", "found_under_slug", "suggested_slug", "disposition", "title", "locator", "locator_status", "tier_guess", "harm_finding", "why_not_admitted", "notes", "created_by_session", "created_at", "resolved_ref_id") VALUES (117, 90, 'accessible-circulation-geometry', 'accessible-circulation-geometry', 'PENDING-VERIFICATION', 'Templer, Mullet, Archea and Margulis (1978) — An analysis of the behavior of stair users (NBS IR 78-1554)', 'doi:10.6028/nbs.ir.78-1554 — National Bureau of Standards internal report. R9 PRE-CHECKED: the DOI is deposited and resolves through Crossref (retrieved this batch); it is not already filed under any ref_id in evidence_sources.', 'RESOLVED', 3, 0, 'NOT ADMITTED, AND THE REASON IS THAT IT IS PROBABLY OFF-PARAMETER. Parameter 3 is ramp gradient; this is a study of STAIR users. It is staged rather than discarded for one reason only: it is the nearest RESOLVABLE item to Table 13 footnote c''s unidentified ''Templer, 1977'', being one year the other side of it and by the same John A. Templer. WHETHER IT IS THE REFERENT IS UNRESOLVED AND IS NOT GUESSED HERE (batch 18 section 9 item 3). The competing candidate is the 1974 dissertation REF-01005''s own bibliography lists. ADMITTING THIS WOULD BE A CATEGORY ERROR unless and until footnote c is tied to it: a stair-behaviour report has no claim to make about ramp gradient, and filing it on parameter 3 would put a stairs figure where a ramp figure belongs. LOCATOR_STATUS IS ''RESOLVED'', WHICH HERE MEANS THE DOI RESOLVES, NOT THAT THE ITEM HAS BEEN READ -- the CHECK offers DEAD, RESOLVED and UNVERIFIED and nothing finer.', 'SURFACED WHILE FAILING TO FIND SOMETHING ELSE, which is the honest provenance. Crossref, queried on the dissertation title REF-01005''s bibliography carries, returned John A. Templer''s indexed corpus instead: this 1978 NBS report, ''The Forgiving Stair'' (1984, Human Factors Society, doi 10.1177/154193128402800118), and ''The Soft Stair: Falls Induced by a Laboratory Stair'' (1989, doi 10.1518/107118189786758148). Full author list here: John A Templer, Gary M Mullet, John Archea, Stephen T Margulis. WHAT MAKES IT CHEAP TO RESOLVE: NBS is now NIST and its internal reports are public, so unlike Walter 1971 and Elmer 1957 this one is very likely retrievable in full without document delivery -- nvlpubs.nist.gov is the route and it has not been tried. IF RETRIEVED, THE QUESTION TO ASK IS NARROW: does it contain any rampway slope or length recommendation at all? If yes, footnote c probably means this and the 1:8/1:10 warrant is identified. If no -- which is what its title predicts -- then footnote c''s Templer is the 1974 dissertation or an item outside every index reached, and either way the warrant for those two bands rests on stair research. THAT QUESTION IS WORTH ONE RETRIEVAL AND NOT MORE.', 'session_2026-09-20-research-batch-19-pre1990-chain-steinfeld-walter-templer', '2026-09-20 03:13', NULL);
UPDATE "search_candidates" SET "notes" = ' || RESOLVED 2026-09-18 (R15, re-described from the source): STAYS PENDING, BUT IT IS NO LONGER A HYPOTHESIS — the record is now verified and the staged description was WRONG ON THE AUTHOR. Batch 17 staged it from REF-00980 deposited reference list as "Walter F." Open Library OL4653562M (retrieved this session) gives: "Four architectural movement studies for the wheelchair and ambulant disabled", by_statement "[studies directed by] Felix Walter.", published by the DISABLED LIVING FOUNDATION, 346 Kensington High St, London, 1971, 60 pp. R15 says correct an over-claim rather than let a guess harden: the CORPORATE author is the Disabled Living Foundation and Walter directed the studies. Neither the reference list nor the catalogue is wrong; they name different things, and the staged row named only one. WHAT THE FULL TEXT WOULD SETTLE, AND WHY IT MATTERS MORE THAN ITS TIER: REF-01005 page 163 reports that Walter and Steinfeld INDEPENDENTLY found 1:16 over 20 feet accessible to at least 95 percent of wheelchair users. That convergence is currently held on Steinfeld testimony alone, so Walter is a single document counted once, not twice. Retrieving it would make the convergence real. NOT RETRIEVED: no digitised copy found via Open Library, Internet Archive or Google Books; HathiTrust returned a Cloudflare interstitial and is unresolved rather than negative. NEXT ROUTE, UNTRIED: Jisc Library Hub Discover, and the Disabled Living Foundation successor organisation. || RESOLVED 2026-09-19 (R15, re-described from the source): RETRACTION OF THIS ROW RETRIEVAL CLAIM, same defect as candidate 110. The re-description above says "no digitised copy found via Open Library, Internet Archive or Google Books". GOOGLE BOOKS WAS NEVER ASKED — HTTP 429, daily quota exceeded. Open Library and Internet Archive stand and were re-derived. The bibliographic record, which is what this row is FOR, is unaffected: Open Library OL4653562M, Disabled Living Foundation, London, 1971, 60 pp, studies directed by Felix Walter. || RESOLVED 2026-09-20 (R15, re-described from the source): R15 UPDATE: THE NAMED NEXT ROUTE IS NOW CLOSED, AND THE ROW GAINS THE HOLDINGS LAYER THAT MAKES DOCUMENT DELIVERY POSSIBLE. This row''s previous re-description ended ''NEXT ROUTE, UNTRIED: Jisc Library Hub Discover, and the Disabled Living Foundation successor organisation.'' JISC WAS TRIED THIS BATCH AND IS UNREACHABLE: two queries, both HTTP 403 carrying a Cloudflare ''Just a moment...'' interstitial, both persisted. NOTHING IS ESTABLISHED ABOUT WHAT JISC HOLDS -- blocked route, not a null -- and it is the second discovery catalogue in two batches to fail this way after HathiTrust. The row should stop naming Jisc as its next step. NOTHING IS RETRACTED FROM THE EARLIER DESCRIPTION: I checked whether batch 18 had missed the Open Library record before writing anything, and it had not -- Felix Walter, DLF, London, 1971, 60 pp is already correctly recorded above, and the corporate-versus-directing-author distinction it draws stands. WHAT IS NEW IS THE IDENTIFIER SET, from the same Open Library edition record OL4653562M re-read this batch: ISBN-10 0901908053, LCCN 77502052, OCLC 222208, LC classification NA2545.P5 D5, Dewey 729/.2, one edition only, publisher address 346 Kensington High St, London W.14, source record marc:marc_loc_2016 -- a LIBRARY OF CONGRESS MARC record, which is why the 1971 date is authoritative rather than inferred, and which independently corroborates the year REF-01005''s Table 13 footnote c gives while that bibliography entry''s own year digits are OCR-damaged. WHY THE IDENTIFIERS ARE THE POINT: GAP-026 says what this needs is a library or document-delivery route and that this is ''a different kind of work from a retrieval ladder''. An OCLC number and an LCCN are exactly what converts that from a search into a request -- interlibrary loan on OCLC 222208, or a direct approach to a holding library. NO SEARCH THIS ENVIRONMENT CAN RUN WILL PRODUCE THE TEXT, and this row should not be handed to another retrieval battery. A NEW SEARCH ROUTE DID WORK AND IS WORTH KEEPING AS METHOD: batch 18 searched Open Library by TITLE and got 0; searching by PUBLISHER, publisher:''Disabled Living Foundation'', returns 99 records and the target is among them. Query shape, not index coverage (R14). STILL THE SAME REASON TO WANT IT: the 1:16-over-20-feet convergence is held on Steinfeld''s testimony about Walter, so it is one document counted once until Walter itself is read.' WHERE "candidate_id" = 109;
UPDATE "search_candidates" SET "notes" = ' || RESOLVED 2026-09-18 (R15, re-described from the source): STAYS PENDING AND ITS DESCRIPTION IS NOW CORROBORATED BY A PRIMARY SOURCE RATHER THAN BY A REFERENCE LIST. Not retrieved: Open Library 0, Google Books 0, Internet Archive 0, ERIC 0. BUT REF-01005 page 163 characterises it directly: "Elmer (1957) found that a 1:8 ramp slope was maximum for wheelchair users. However, his sample was taken from wheelchair users at a pioneering rehabilitation-education center and the findings probably reflect the high standard of excellence in rehabilitation training that the subjects received as part of their program." SO THE 1957 FINDING IS 1:8, AND THE FIELD OWN 1979 ASSESSMENT IS THAT IT IS UNREPRESENTATIVE BECAUSE THE SAMPLE WAS ELITE-TRAINED. That is a selection-bias critique published eight years before the ADA, and it is itself first-class historical evidence about how the threshold literature was weighed. A WEB SEARCH SUMMARY ASSERTED THIS WAS A UNIVERSITY OF IOWA MASTER THESIS AND NONE OF ITS OWN RETURNED LINKS SUPPORTED THAT — the claim is discarded, not recorded (CLAUDE.md 5(c)). The institution is NOT established: REF-01005 says only "a pioneering rehabilitation-education center" and naming one would be invention. || RESOLVED 2026-09-19 (R15, re-described from the source): RETRACTION OF THIS ROW OWN RETRIEVAL CLAIM. The re-description above states "Not retrieved: Open Library 0, Google Books 0, Internet Archive 0, ERIC 0". GOOGLE BOOKS 0 IS FALSE. That query returned HTTP 429 (daily quota exceeded) and was never asked; recording an unfired query as a null is the error batch 17 made on SafetyLit and is corrected here rather than left standing. THE OTHER THREE ZEROS HOLD and were re-derived, not assumed: Open Library numFound 0, Internet Archive 0 relevant, ERIC 0. EVERYTHING ELSE IN THE ROW IS UNAFFECTED — Elmer 1957 finding of 1:8 maximum, and Steinfeld 1979 dismissal of it as an elite-trained sample, come from REF-01005 page 163 and stand on a retrieved primary source. || RESOLVED 2026-09-20 (R15, re-described from the source): R15 RE-DESCRIPTION FROM A PRIMARY SOURCE, AND THE ROW GAINS AN AUTHOR IT NEVER HAD. Staged from REF-00980''s Crossref reference list as a bare title with a year, ''A study to determine the specifications of wheelchair ramps (1957)''. REF-01005 supplies three things the reference list did not, from two different places in the same document. (1) THE AUTHOR AND THE FORM, from its bibliography at pypdf page index 167: ''Elmer, C.D. [A s]t[udy] to determine the s[p]e[ci]fications of wheelchai[r] ramp[s]. Ph.D. d[is]ser[ta]tion, University o[f] Il[linois]''. NOTE HONESTLY: the bibliography''s own year digits are OCR-damaged and read ''194-5/'', which is NOT 1957 and is not resolvable from those bytes. (2) THE YEAR, from the body text at page index 162, which reads ''Elmer (1957)'' cleanly -- so 1957 is corroborated by a primary source, but by the prose, not by the reference entry. (3) THE FINDING, which is why this row now matters more than it did: REF-01005 reports that ''Elmer (1957) found that a 1:8 ramp slope was maximum for wheelchair users'' and then DISCOUNTS IT ON SAMPLING -- his subjects were young, highly trained users at a pioneering rehabilitation-education centre, where Walter''s sample and Steinfeld''s own included large proportions of older people and many with reduced arm function and low stamina. Captured as extraction 57 with contested=1. WHAT THIS CHANGES ABOUT THE ROW''S VALUE: staged as a hypothesis that the oldest ramp-specification study might be the origin of a threshold still in force. It is not that. Its figure is 1:8, which no code carries, and the 1979 report set it aside forty-seven years ago for a reason this project would give today. THE HISTORICAL TRAJECTORY IS THE FINDING: 1:8 (1957, discounted as unrepresentative) -> 1:12 (ANSI, measured and found wanting in 1979) -> 1:16 (Walter 1971 and Steinfeld 1979 converge) -> 1:20 (every wheelchair user in Steinfeld''s sample completed 40 feet). THE PARAMETER HAS MOVED IN ONE DIRECTION, GENTLER, FOR SEVENTY YEARS, AND EACH STEP WAS DRIVEN BY WIDENING THE SAMPLE. NOT RETRIEVED AND STILL OWED as a document: a 1957 Illinois PhD dissertation. ProQuest Dissertations and the University of Illinois institutional repository are the routes and neither has been tried. NOT AN ANCHOR IF RETRIEVED: owner ruling 2026-09-18 places pre-1990 work as historical grounding.' WHERE "candidate_id" = 110;
UPDATE "search_candidates" SET "notes" = 'HYPOTHESIS, per R15 — this description is a guess until the item is read. REF-01005 Table 13 (Maximum Lengths and Slopes for Rampways) carries footnote c: "Based on research of others (Templer, 1977 and Walter, 1971)." SO THE HUD REPORT RECOMMENDATION TABLE IS NOT FOUNDED ON ITS OWN RAMP EXPERIMENT ALONE, which is the most important structural fact this batch found about the provenance chain: the numbers that reached ANSI A117.1 came from a synthesis of three studies, only one of which this project now holds. REF-00980 deposited reference list separately holds Templer J A (1984), "Guidelines for accommodating the handicapped on crossings: final report" — a DIFFERENT item, possibly a successor. WHICH TEMPLER IS LOAD-BEARING IS UNRESOLVED AND MUST NOT BE GUESSED. Nothing in any payload this session holds names Templer institution or other work, so none is recorded. Routes to try: ERIC, NTIS, and the TRID index that already held REF-01002. || RESOLVED 2026-09-20 (R15, re-described from the source): R15 CORRECTION OF AN OVER-CLAIM IN THIS ROW''S OWN TITLE. The row was staged as ''Templer J A (1977) -- the ramp-slope research REF-01005 Table 13 names as one of its two warrants''. CALLING IT RAMP-SLOPE RESEARCH WAS A GUESS AND IT LOOKS WRONG. Two findings, neither of which resolves the item, and the assignment''s instruction that which Templer is load-bearing MUST NOT BE GUESSED is held to. (1) TEMPLER 1977 IS NOT IN REF-01005''S OWN BIBLIOGRAPHY. Table 13 footnote c cites ''Templer, 1977''; the reference list, transcribed this batch from pypdf page index 169, carries ''Templer, J.A. Stair sha[p]e and h[u]man movement, Unpublished doct[o]ral [dis]sertation. New [York]: [?] [Un]iversity, 1974.'' The year digits 1974 are clean in the OCR. So the report cites a year its own reference list does not carry. (2) NO TEMPLER 1977 EXISTS IN ANY INDEX REACHED, and John A. Templer''s corpus is STAIRS. Derive it: ERIC author:Templer returns 33 records, none architectural; ERIC Templer AND stairs returns 0; OpenAlex Templer + 1977 returns 10, none architectural; Crossref on the dissertation title returns his real corpus -- ''An analysis of the behavior of stair users'' (Templer, Mullet, Archea, Margulis, 1978, NBS internal report, DOI 10.6028/nbs.ir.78-1554), ''The Forgiving Stair'' (1984), ''The Soft Stair'' (1989). FOUR ITEMS ACROSS FIFTEEN YEARS, NOT ONE ABOUT RAMPS. WHAT THE ROW NOW ASSERTS, AND ONLY THIS: footnote c names a Templer as one of two warrants for Table 13''s 1:8 and 1:10 bands; the referent is unidentified; the two nearest candidates are the 1974 dissertation the report itself lists and the 1978 NBS report one year the other side, and THIS PASS DOES NOT CHOOSE BETWEEN THEM. WHY IT STILL MATTERS IF IT IS NEVER IDENTIFIED: whichever item footnote c meant, the person it names has no ramp research, so the warrant for the steepest rampway bands leans on stair-user behaviour. SCOPE CORRECTION THAT CUTS THE OTHER WAY AND REDUCES THIS ROW''S PRIORITY: extraction 56 records that footnote c''s marker appears on the 1:8 and 1:10 rows ONLY, not on 1:12 or 1:16 -- the bands Steinfeld actually tested. So Templer warrants the permissive end of the table, which no determination would rest on. GAP-037 treats retrieving Templer as one of two remaining nodes of the 1:12 chain; on this reading it is not part of that chain at all. This row stays PENDING-VERIFICATION rather than being retired, because a cleaner scan of page 57 could overturn the footnote-scope reading and put it back.' WHERE "candidate_id" = 115;

