INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (56, 'REF-01005', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'US', NULL, 'qualitative', 'warrant scoped to the 1:8 and 1:10 bands only', NULL, 'Based on research of others (Templer, 1977 and Walter, 1971).', 'Table 13: Maximum Lengths and Slopes for Rampways -- footnote c', NULL, 'committee_assertion', NULL, NULL, NULL, NULL, NULL, NULL, 0, 'retrieval-log/session_2026-09-18-research-batch-18-archive-route-ramp-threshold/5dd866a236fb5978.pdf', 'page', NULL, NULL, '57', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'reviewed', NULL, 'THE WARRANT IS SCOPED, AND THE SCOPE IS THE FINDING. Table 13 lists four allowable slope bands -- 12.5 percent (1:8), 10.0 percent (1:10), 8.3 percent (1:12) and 6.25 percent (1:16). THE FOOTNOTE MARKER c APPEARS ON THE FIRST TWO AND NOT ON THE LAST TWO. Derive it rather than trusting this sentence: pypdf page index 56 renders the four rows as ''If slope12.5% (1:8)orless steepc.'', ''If slope-10.0% (1:10) or less steepc'', ''If slope*8.3% (1:12) or less.steep'', and ''If. slope.6.25% (1:16) or less steep''. WHY THE READING IS COHERENT RATHER THAN OCR NOISE: Table 12 (page index 55) shows the study tested exactly three slopes, 1:12, 1:16 and 1:20. The two bands carrying footnote c are precisely the two OUTSIDE the tested range, so the report warrants by others exactly what it did not measure itself. WHAT THIS CHANGES: GAP-037 records that Table 13 rests partly on others and treats Templer 1977 and Walter 1971 as the two remaining nodes of the 1:12 chain. That is right about Walter and OVERSTATED about Templer for the anchoring question -- on this reading the named warrant covers the 1:8 and 1:10 rows, the permissive end no determination would rest on, while the 1:12 and 1:16 rows rest on the study''s own data. NO COMPARATOR EDGE: condition_on and derived_from both require a referent this project holds as a row, and Templer 1977 and Walter 1971 are candidates, not rows. The edge becomes writable if either is admitted. STATED AS A READING, NOT AS SETTLED: the markers are single characters on a damaged scan. A cleaner copy of page 57 would confirm or refute it in one look, and until then the scoping claim is held at this confidence and not promoted. [VERBATIM-EXEMPT: OCR-NOT-DECODABLE: scanned 1979 microfiche ED184280.pdf (sha256 5dd866a236fb59788dbff4b4ca80c4da8890274259b0cb6941a83c1c370fb751), bound to REF-01005. quote_in_artefacts cannot decode a PDF text layer. Re-derive with pypdf at page index 56, which holds ''cBased on research of others (Templer, 1977 and-WaJter$, 1971).'' -- the OCR damage is on ''Walter'' and on the footnote marker, which is why claim_text is normalised.]', '2026-09-20 03:01', 'session_2026-09-20-research-batch-19-pre1990-chain-steinfeld-walter-templer', '2026-09-20 03:01', 'session_2026-09-20-research-batch-19-pre1990-chain-steinfeld-walter-templer', 'condition', NULL);
INSERT INTO "source_value_extractions" ("extraction_id", "ref_id", "slug", "parameter_id", "identity_code", "icf_code", "needs_code", "medical_code", "jurisdiction", "setting", "claim_type", "claimed_value", "claimed_unit", "claim_text", "source_section", "root_id", "root_type", "root_ref_id", "echo_of", "measurement_paradigm", "device_class", "root_population_note", "root_classification_basis", "contested", "file_anchor", "locator_scheme", "loc_division", "loc_part", "loc_section", "loc_subsection", "loc_paragraph", "loc_clause", "loc_subclause", "loc_division_end", "loc_part_end", "loc_section_end", "loc_subsection_end", "loc_paragraph_end", "loc_clause_end", "loc_subclause_end", "loc_note", "extraction_method", "extraction_status", "promoted_to_rdc_id", "notes", "created_at", "created_by_session", "updated_at", "updated_by_session", "figure_role", "comparator") VALUES (57, 'REF-01005', 'accessible-circulation-geometry', 3, 'MOB', NULL, NULL, NULL, 'US', NULL, 'numerical', '1:8', 'ratio', 'Elmer (1957) found that a 1:8 ramp slope was maximum for wheelchair users. However, his sample was taken from wheelchair users at a pioneering rehabilitation-education center and the findings probably reflect the high standard of excellence in rehabilitation training that the subjects received as part of their program. Both Walter''s and our sample included large proportions of older people and many with reduced arm function and low stamina. The Elmer sample was much younger in age.', 'Comparison with Previous Research -- 5. Ramps', NULL, 'measurement_primary', NULL, NULL, NULL, NULL, 'Per REF-01005: Elmer''s subjects were wheelchair users at a pioneering rehabilitation-education centre, much younger than REF-01005''s own sample, and trained to a high standard. REF-01005''s own sample and Walter''s both included large proportions of older people and many with reduced arm function and low stamina.', 'Reported second-hand by REF-01005. root_ref_id is deliberately NULL: Elmer 1957 is search_candidates 110, not an admitted source, so there is no row to point at. This is NOT a claim that REF-01005 measured 1:8 -- it did not; it tested 1:12, 1:16 and 1:20 only (Table 12, page index 55).', 1, 'retrieval-log/session_2026-09-18-research-batch-18-archive-route-ramp-threshold/5dd866a236fb5978.pdf', 'page', NULL, NULL, '163', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'full-read', 'reviewed', NULL, 'R7 FIRST-CLASS INADEQUACY RECORD, AND IT DATES A CANDIDATE. TWO THINGS ARE CAPTURED. (1) THE FIGURE: the earliest ramp-specification study this corpus has any trace of found 1:8 -- 12.5 percent -- acceptable as a maximum. That is HALF AS GENTLE AGAIN as the 1:12 the codes carry and roughly twice as steep as the 1:16 both later studies converge on, so the historical trajectory of this parameter runs consistently toward GENTLER, never steeper. (2) WHY IT WAS SET ASIDE, WHICH IS THE MORE USEFUL HALF: REF-01005 rejects Elmer''s generalisability on SAMPLING, not on method -- young, highly trained users at a rehabilitation-education centre versus samples containing older people, reduced arm function and low stamina. That is the literature performing the exact correction this guidebook''s epistemics are built around, in 1979, in its own words. CONTESTED=1 IS SET FOR THAT REASON. THIS ALSO DATES SEARCH CANDIDATE 110: the candidate was staged as ''A study to determine the specifications of wheelchair ramps (1957)'' from a Crossref reference list, and REF-01005''s body text independently says ''Elmer (1957)'', while its bibliography supplies the author (Elmer, C.D.) and the form (Ph.D. dissertation, University of Il[linois]) -- the bibliography''s own year digits are OCR-damaged and read ''194-5/'', so 1957 comes from the body text, not from the reference entry. NOT AN ANCHOR AND NOT A ROUTE TO ONE: owner ruling 2026-09-18 puts pre-1990 work at historical grounding, and this is a 1957 figure reported second-hand in a 1979 document. [VERBATIM-EXEMPT: OCR-NOT-DECODABLE: scanned 1979 microfiche ED184280.pdf (sha256 5dd866a236fb59788dbff4b4ca80c4da8890274259b0cb6941a83c1c370fb751), bound to REF-01005. quote_in_artefacts cannot decode a PDF text layer. Re-derive with pypdf at page index 162, which holds "Elmer (1957) found thata 1:8''ramp slope was maximum | Jot- wheelchair users" and "The Elmer sample was | much younger in age". OCR damage on ''for'', ''pioneering'' and ''high'' is why claim_text is normalised.]', '2026-09-20 03:02', 'session_2026-09-20-research-batch-19-pre1990-chain-steinfeld-walter-templer', '2026-09-20 03:02', 'session_2026-09-20-research-batch-19-pre1990-chain-steinfeld-walter-templer', 'finding', NULL);